import sys
import os
import time
from datetime import datetime

SEEN_FILE = 'seen.dat'
LOG_FILE = 'seen.log'

def load_seen():
    try:
        with open(SEEN_FILE, 'r') as f:
            return set(line.strip() for line in f if line.strip())
    except (IOError, OSError):
        return set()

def save_seen(seen):
    try:
        with open(SEEN_FILE, 'w') as f:
            f.write('\n'.join(sorted(seen)))
    except IOError as e:
        raise SystemExit(1) from e

def log_run(new_count, total_count, load_failed):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    summary = f'run new={new_count} total={total_count}' if not load_failed else 'load-failed'
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(f'{timestamp} {summary}\n')
    except IOError as e:
        raise SystemExit(1) from e

def main():
    seen = load_seen()
    new_count = 0
    total_count = len(seen)

    for line in sys.stdin:
        stripped = line.strip()
        if not stripped:
            continue
        if stripped not in seen:
            print(f'NEW {stripped}')
            seen.add(stripped)
            new_count += 1
        else:
            print(f'SEEN {stripped}')

    total_count = len(seen)
    save_seen(seen)
    log_run(new_count, total_count, not seen)
    sys.exit(0)

if __name__ == '__main__':
    main()

